// tor_onion_tool.cpp
// Single-file C++17 source that:
// - Performs real WinHTTP GET/POST requests to .onion hosts through a Tor SOCKS5 proxy
// - Downloads and parses a Tor consensus document (extracting validity interval and router lines)
// - Downloads and parses a Tor v3 hidden service descriptor (extracting key fields)
// - Validates v3 .onion addresses (base32 decode + checksum) using OpenSSL
//
// Build (MSVC):
//   cl /std:c++17 /O2 /EHsc tor_onion_tool.cpp winhttp.lib
//   (also link OpenSSL libcrypto if needed, e.g., /link libcrypto.lib)
//
// Example usage (Tor must be running a SOCKS proxy, e.g., 127.0.0.1:9050):
//   tor_onion_tool.exe --socks socks=127.0.0.1:9050 --get http://expyuzz4wqqyqhjn.onion/
//   tor_onion_tool.exe --socks socks=127.0.0.1:9050 --post http://expyuzz4wqqyqhjn.onion/ "name=value"
//   tor_onion_tool.exe --consensus-url https://collector.torproject.org/recent/relay-descriptors/consensuses/2024-01-01-00-00-00-consensus
//   tor_onion_tool.exe --descriptor-url https://collector.torproject.org/recent/relay-descriptors/extra-infos/<somefile>
//   tor_onion_tool.exe --onion-check facebookcorewwwi.onion

#define UNICODE
#define _UNICODE
#include <windows.h>
#include <winhttp.h>

#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>
#include <sstream>
#include <iostream>
#include <iomanip>
#include <algorithm>
#include <cctype>
#include <map>
#include <array>
#include <memory>

#include <openssl/evp.h>
