// UTF-8 <-> UTF-16 helpers
static std::wstring Utf8ToWide(const std::string& s) {
    if (s.empty()) return L"";
    int len = MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), nullptr, 0);
    std::wstring w(len, 0);
    MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), &w[0], len);
    return w;
}
static std::string WideToUtf8(const std::wstring& w) {
    if (w.empty()) return "";
    int len = WideCharToMultiByte(CP_UTF8, 0, w.c_str(), (int)w.size(), nullptr, 0, nullptr, nullptr);
    std::string s(len, 0);
    WideCharToMultiByte(CP_UTF8, 0, w.c_str(), (int)w.size(), &s[0], len, nullptr, nullptr);
    return s;
}

// Error helper
static std::string LastErrorMessage(DWORD code = GetLastError()) {
    LPWSTR buf = nullptr;
    DWORD n = FormatMessageW(FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,
                             NULL, code, MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT),
                             (LPWSTR)&buf, 0, NULL);
    std::string msg = (n && buf) ? WideToUtf8(buf) : "Unknown error";
    if (buf) LocalFree(buf);
    std::ostringstream oss;
    oss << "Win32Error " << code << ": " << msg;
    return oss.str();
}

// RAII for WinHTTP handles
struct WinHttpHandle {
    HINTERNET h = nullptr;
    WinHttpHandle() = default;
    explicit WinHttpHandle(HINTERNET h_) : h(h_) {}
    ~WinHttpHandle() { if (h) WinHttpCloseHandle(h); }
    WinHttpHandle(const WinHttpHandle&) = delete;
    WinHttpHandle& operator=(const WinHttpHandle&) = delete;
    WinHttpHandle(WinHttpHandle&& o) noexcept : h(o.h) { o.h = nullptr; }
    WinHttpHandle& operator=(WinHttpHandle&& o) noexcept { if (this != &o) { if (h) WinHttpCloseHandle(h); h = o.h; o.h = nullptr; } return *this; }
    operator HINTERNET() const { return h; }
    bool valid() const { return h != nullptr; }
};

struct HttpResponse {
    int status = 0;
    std::map<std::string, std::string> headers;
    std::vector<uint8_t> body;
};

static bool ParseUrl(const std::wstring& url, std::wstring& host, INTERNET_PORT& port, std::wstring& path, bool& secure) {
    URL_COMPONENTS uc{};
    uc.dwStructSize = sizeof(uc);
    wchar_t hostBuf[512]; wchar_t pathBuf[2048];
    uc.lpszHostName = hostBuf; uc.dwHostNameLength = _countof(hostBuf);
    uc.lpszUrlPath = pathBuf;  uc.dwUrlPathLength = _countof(pathBuf);
    if (!WinHttpCrackUrl(url.c_str(), (DWORD)url.size(), 0, &uc)) return false;
    host.assign(uc.lpszHostName, uc.dwHostNameLength);
    path.assign(uc.lpszUrlPath, uc.dwUrlPathLength);
    if (path.empty()) path = L"/";
    port = uc.nPort;
    secure = (uc.nScheme == INTERNET_SCHEME_HTTPS);
    return true;
}

static HttpResponse HttpRequest(const std::wstring& method, const std::wstring& url, const std::vector<uint8_t>& body = {}, const std::wstring& extraHeaders = L"") {
    std::wstring host, path; INTERNET_PORT port = 0; bool secure = false;
    if (!ParseUrl(url, host, port, path, secure)) throw std::runtime_error("Invalid URL");
    WinHttpHandle session(WinHttpOpen(L"tor-client/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0));
    if (!session.valid()) throw std::runtime_error("WinHttpOpen failed: " + LastErrorMessage());
    DWORD secureFlags = WINHTTP_FLAG_SECURE;
    WinHttpHandle connect(WinHttpConnect(session, host.c_str(), port, 0));
    if (!connect.valid()) throw std::runtime_error("WinHttpConnect failed: " + LastErrorMessage());
    WinHttpHandle request(WinHttpOpenRequest(connect, method.c_str(), path.c_str(), NULL, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, secure ? secureFlags : 0));
    if (!request.valid()) throw std::runtime_error("WinHttpOpenRequest failed: " + LastErrorMessage());

    // Strong TLS options
    DWORD flags = SECURITY_FLAG_IGNORE_UNKNOWN_CA; // leave default validation; do not disable hostname checks
    // Do not set insecure flags by default.

    // Timeouts
    WinHttpSetTimeouts(request, 15000, 15000, 30000, 30000);

    // Headers
    std::wstring headers = L"Accept: */*\r\nConnection: close\r\n";
    if (!extraHeaders.empty()) headers += extraHeaders;

    // Send
    BOOL ok = WinHttpSendRequest(request,
                                 headers.c_str(), (DWORD)headers.size(),
                                 body.empty() ? WINHTTP_NO_REQUEST_DATA : (LPVOID)body.data(),
                                 (DWORD)body.size(),
                                 (DWORD)body.size(),
                                 0);
    if (!ok) throw std::runtime_error("WinHttpSendRequest failed: " + LastErrorMessage());

    if (!WinHttpReceiveResponse(request, NULL)) throw std::runtime_error("WinHttpReceiveResponse failed: " + LastErrorMessage());

    // Status
    DWORD statusCode = 0, size = sizeof(statusCode);
    if (!WinHttpQueryHeaders(request, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &statusCode, &size, WINHTTP_NO_HEADER_INDEX))
        throw std::runtime_error("WinHttpQueryHeaders(status) failed: " + LastErrorMessage());

    // Headers (raw)
    DWORD headerSize = 0;
    WinHttpQueryHeaders(request, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, WINHTTP_NO_OUTPUT_BUFFER, &headerSize, WINHTTP_NO_HEADER_INDEX);
    std::wstring raw;
    if (GetLastError() == ERROR_INSUFFICIENT_BUFFER) {
        raw.resize(headerSize / sizeof(wchar_t));
        if (!WinHttpQueryHeaders(request, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, &raw[0], &headerSize, WINHTTP_NO_HEADER_INDEX))
            throw std::runtime_error("WinHttpQueryHeaders(raw) failed: " + LastErrorMessage());
    }
    std::map<std::string, std::string> hdrs;
    {
        std::istringstream iss(WideToUtf8(raw));
        std::string line;
        while (std::getline(iss, line)) {
            if (line.size() && (line.back() == '\r' || line.back() == '\n')) line.pop_back();
            auto pos = line.find(':');
            if (pos != std::string::npos) {
                std::string k = line.substr(0, pos);
                std::string v = line.substr(pos + 1);
                while (!v.empty() && (v.front() == ' ' || v.front() == '\t')) v.erase(v.begin());
                hdrs[k] = v;
            }
        }
    }

    // Body
    std::vector<uint8_t> resp;
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(request, &avail)) throw std::runtime_error("WinHttpQueryDataAvailable failed: " + LastErrorMessage());
        if (!avail) break;
        size_t off = resp.size();
        resp.resize(off + avail);
        DWORD read = 0;
        if (!WinHttpReadData(request, resp.data() + off, avail, &read)) throw std::runtime_error("WinHttpReadData failed: " + LastErrorMessage());
        resp.resize(off + read);
    }
    HttpResponse r;
    r.status = (int)statusCode;
    r.headers = std::move(hdrs);
    r.body = std::move(resp);
    return r;
}

