// Base64 helpers
static std::vector<uint8_t> Base64Decode(const std::string& in) {
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO* bio = BIO_new_mem_buf(in.data(), (int)in.size());
    b64 = BIO_push(b64, bio);
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    std::vector<uint8_t> out(in.size());
    int len = BIO_read(b64, out.data(), (int)out.size());
    if (len < 0) len = 0;
    out.resize((size_t)len);
    BIO_free_all(b64);
    return out;
}
static std::string Base64Encode(const uint8_t* data, size_t len) {
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO* bio = BIO_new(BIO_s_mem());
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    BIO_push(b64, bio);
    BIO_write(b64, data, (int)len);
    BIO_flush(b64);
    BUF_MEM* mem = nullptr;
    BIO_get_mem_ptr(b64, &mem);
    std::string out(mem && mem->data ? std::string(mem->data, mem->length) : "");
    BIO_free_all(b64);
    return out;
}

// Base32 (RFC4648, lowercase) for onion v3
static const char* BASE32_ALPH = "abcdefghijklmnopqrstuvwxyz234567";
static int Base32Index(char c) {
    if (c >= 'A' && c <= 'Z') c = (char)std::tolower(c);
    const char* p = std::strchr(BASE32_ALPH, c);
    return p ? int(p - BASE32_ALPH) : -1;
}
static std::vector<uint8_t> Base32Decode(const std::string& s) {
    std::vector<uint8_t> out;
    int buffer = 0, bitsLeft = 0;
    for (char c : s) {
        if (c == '=' || c == ' ' || c == '\r' || c == '\n' || c == '\t') continue;
        int val = Base32Index(c);
        if (val < 0) throw std::runtime_error("Invalid base32");
        buffer = (buffer << 5) | val;
        bitsLeft += 5;
        if (bitsLeft >= 8) {
            bitsLeft -= 8;
            out.push_back(uint8_t((buffer >> bitsLeft) & 0xFF));
        }
    }
    return out;
}
static std::string Base32Encode(const uint8_t* data, size_t len) {
    std::string out;
    int buffer = 0, bitsLeft = 0;
    for (size_t i = 0; i < len; ++i) {
        buffer = (buffer << 8) | data[i];
        bitsLeft += 8;
        while (bitsLeft >= 5) {
            bitsLeft -= 5;
            out.push_back(BASE32_ALPH[(buffer >> bitsLeft) & 31]);
        }
    }
    if (bitsLeft) out.push_back(BASE32_ALPH[(buffer << (5 - bitsLeft)) & 31]);
    return out;
}

// Tor consensus minimal parser
struct TorRelay {
    std::string nickname;
    std::string identity; // hex
    std::string address;
    int or_port = 0;
    bool running = false;
    bool valid = false;
};
struct TorConsensus {
    std::string valid_after;
    std::string fresh_until;
    std::string valid_until;
    std::vector<TorRelay> relays;
};

static TorConsensus ParseConsensusText(const std::string& text) {
    TorConsensus c;
    std::istringstream iss(text);
    std::string line;
    TorRelay current{};
    bool inRouter = false;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.rfind("valid-after ", 0) == 0) c.valid_after = line.substr(12);
        else if (line.rfind("fresh-until ", 0) == 0) c.fresh_until = line.substr(12);
        else if (line.rfind("valid-until ", 0) == 0) c.valid_until = line.substr(12);
        else if (line.rfind("r ", 0) == 0) {
            if (inRouter) c.relays.push_back(current);
            inRouter = true;
            current = TorRelay{};
            // r nickname identity digest publication IP ORPort DirPort
            std::istringstream rs(line);
            std::string tag, nickname, identity_b64, digest_b64, pub, ip; int orp = 0, dirp = 0;
            rs >> tag >> nickname >> identity_b64 >> digest_b64 >> pub >> ip >> orp >> dirp;
            current.nickname = nickname;
            // identity_b64 is base64 of RSA identity digest (20 bytes). Store as hex for display.
            auto id = Base64Decode(identity_b64 + "="); // base64 without padding in consensus; add one '='
            std::ostringstream hx;
            for (auto b : id) hx << std::hex << std::setw(2) << std::setfill('0') << (int)b;
            current.identity = hx.str();
            current.address = ip;
            current.or_port = orp;
        } else if (line.rfind("s ", 0) == 0) {
            // flags line
            current.running = (line.find(" Running") != std::string::npos) || (line.find(" Running") != std::string::npos) || (line.find(" Running") != std::string::npos);
            current.valid = (line.find(" Valid") != std::string::npos);
        }
    }
    if (inRouter) c.relays.push_back(current);
    return c;
}

// Tor v3 onion address validation and pubkey extraction
// v3 address: base32(lower) of: PUBKEY(32) | CHECKSUM(2) | VERSION(1), length 56 chars, plus ".onion"
static bool ValidateOnionV3(const std::string& onionHost, std::array<uint8_t,32>& pubkeyOut) {
    std::string h = onionHost;
    std::string suffix = ".onion";
    if (h.size() > suffix.size() && h.substr(h.size() - suffix.size()) == suffix) {
        h = h.substr(0, h.size() - suffix.size());
    }
    std::transform(h.begin(), h.end(), h.begin(), [](unsigned char c){ return (char)std::tolower(c); });
    if (h.size() != 56) return false;
    std::vector<uint8_t> bytes;
    try { bytes = Base32Decode(h); } catch (...) { return false; }
    if (bytes.size() != 35) return false;
    std::array<uint8_t,32> pub{}; std::copy(bytes.begin(), bytes.begin()+32, pub.begin());
    uint8_t csum0 = bytes[32], csum1 = bytes[33], ver = bytes[34];
    if (ver != 3) return false;

    // checksum = first 2 bytes of SHA3-256(".onion checksum" | pubkey | version)
    const char* tag = ".onion checksum";
    std::vector<uint8_t> m; m.insert(m.end(), tag, tag + std::strlen(tag));
    m.insert(m.end(), pub.begin(), pub.end());
    m.push_back(ver);

    uint8_t digest[32];
#if OPENSSL_VERSION_NUMBER >= 0x10100000L
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(ctx, EVP_sha3_256(), nullptr);
    EVP_DigestUpdate(ctx, m.data(), m.size());
    unsigned int outl = 0;
    EVP_DigestFinal_ex(ctx, digest, &outl);
    EVP_MD_CTX_free(ctx);
#else
    // Fallback to SHA256 if SHA3 not available (best-effort validation)
    SHA256(m.data(), m.size(), digest);
#endif
    if (digest[0] != csum0 || digest[1] != csum1) return false;
    pubkeyOut = pub;
    return true;
}

// Hidden service descriptor minimal text parser (HSv3 descriptor format is multi-part and signed; here we extract obvious fields from a text copy)
struct HSDescriptor {
    std::string descriptor_lifetime;
    std::string revision_counter;
    std::string superencrypted; // base64 block (opaque)
    std::vector<std::string> intro_points; // opaque lines
};
static HSDescriptor ParseHSDescriptor(const std::string& text) {
    HSDescriptor d;
    std::istringstream iss(text);
    std::string line;
    bool inSuper = false;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.rfind("descriptor-lifetime ", 0) == 0) d.descriptor_lifetime = line.substr(20);
        else if (line.rfind("revision-counter ", 0) == 0) d.revision_counter = line.substr(17);
        else if (line == "superencrypted") { inSuper = true; }
        else if (line == "-----BEGIN MESSAGE-----") { inSuper = true; d.superencrypted.clear(); }
        else if (line == "-----END MESSAGE-----") { inSuper = false; }
        else if (inSuper) {
            if (!line.empty() && std::all_of(line.begin(), line.end(), [](unsigned char c){ return std::isalnum(c) || c=='+' || c=='/' || c=='='; })) {
                d.superencrypted += line;
            }
        } else if (line.rfind("introduction-point ", 0) == 0) {
            d.intro_points.push_back(line.substr(19));
        }
    }
    return d;
}

// Simple CLI
static void PrintUsage() {
    std::cout << "Options:\n"
              << "  --consensus-url <url>\n"
              << "  --descriptor-url <url>\n"
              << "  --validate-onion <host.onion>\n"
              << "  --get <https-url>\n"
              << "  --post <https-url> <body>\n";
}

int wmain(int argc, wchar_t* argv[]) {
    try {
        std::vector<std::wstring> args(argv + 1, argv + argc);
        std::wstring consensusUrl, descriptorUrl, getUrl, postUrl;
        std::wstring postBodyW;
        std::wstring validateOnionW;
        for (size_t i = 0; i < args.size(); ++i) {
            if (args[i] == L"--consensus-url" && i + 1 < args.size()) { consensusUrl = args[++i]; }
            else if (args[i] == L"--descriptor-url" && i + 1 < args.size()) { descriptorUrl = args[++i]; }
            else if (args[i] == L"--validate-onion" && i + 1 < args.size()) { validateOnionW = args[++i]; }
            else if (args[i] == L"--get" && i + 1 < args.size()) { getUrl = args[++i]; }
            else if (args[i] == L"--post" && i + 2 < args.size()) { postUrl = args[++i]; postBodyW = args[++i]; }
            else if (args[i] == L"--help") { PrintUsage(); return 0; }
        }

        if (!consensusUrl.empty()) {
            auto r = HttpRequest(L"GET", consensusUrl);
            if (r.status != 200) throw std::runtime_error("Consensus HTTP status " + std::to_string(r.status));
            std::string body(r.body.begin(), r.body.end());
            auto c = ParseConsensusText(body);
            std::cout << "Consensus: valid-after=" << c.valid_after << " fresh-until=" << c.fresh_until << " valid-until=" << c.valid_until << "\n";
            std::cout << "Relays parsed: " << c.relays.size() << "\n";
            size_t shown = 0;
            for (const auto& rr : c.relays) {
                std::cout << " - " << rr.nickname << " " << rr.address << ":" << rr.or_port << " id=" << rr.identity << (rr.running ? " Running" : "") << (rr.valid ? " Valid" : "") << "\n";
                if (++shown >= 5) break;
            }
        }

        if (!descriptorUrl.empty()) {
            auto r = HttpRequest(L"GET", descriptorUrl);
            if (r.status != 200) throw std::runtime_error("Descriptor HTTP status " + std::to_string(r.status));
            std::string body(r.body.begin(), r.body.end());
            auto d = ParseHSDescriptor(body);
            std::cout << "Descriptor: lifetime=" << d.descriptor_lifetime << " revision=" << d.revision_counter << "\n";
            std::cout << "Intro points: " << d.intro_points.size() << "\n";
            if (!d.superencrypted.empty()) {
                auto blob = Base64Decode(d.superencrypted);
                std::cout << "Superencrypted blob bytes: " << blob.size() << "\n";
            }
        }

        if (!validateOnionW.empty()) {
            std::string host = WideToUtf8(validateOnionW);
            std::array<uint8_t,32> pub{};
            bool ok = ValidateOnionV3(host, pub);
            std::cout << "Validate " << host << ": " << (ok ? "OK" : "FAIL") << "\n";
            if (ok) {
                std::cout << "PubKey: ";
                for (auto b : pub) std::cout << std::hex << std::setw(2) << std::setfill('0') << (int)b;
                std::cout << std::dec << "\n";
            }
        }

        if (!getUrl.empty()) {
            auto r = HttpRequest(L"GET", getUrl);
            std::cout << "GET status: " << r.status << " bytes: " << r.body.size() << "\n";
            if (!r.body.empty()) {
                std::string snip(r.body.begin(), r.body.begin() + std::min<size_t>(r.body.size(), 512));
                std::cout << snip << (r.body.size() > 512 ? "..." : "") << "\n";
            }
        }

        if (!postUrl.empty()) {
            std::string body = WideToUtf8(postBodyW);
            std::vector<uint8_t> data(body.begin(), body.end());
            std::wstring hdrs = L"Content-Type: application/x-www-form-urlencoded\r\n";
            auto r = HttpRequest(L"POST", postUrl, data, hdrs);
            std::cout << "POST status: " << r.status << " bytes: " << r.body.size() << "\n";
            if (!r.body.empty()) {
                std::string snip(r.body.begin(), r.body.begin() + std::min<size_t>(r.body.size(), 512));
                std::cout << snip << (r.body.size() > 512 ? "..." : "") << "\n";
            }
        }

        if (consensusUrl.empty() && descriptorUrl.empty() && validateOnionW.empty() && getUrl.empty() && postUrl.empty()) {
            PrintUsage();
        }

        return 0;
    } catch (const std::exception& ex) {
        std::cerr << "Error: " << ex.what() << "\n";
        return 1;
    }
}

// tor_client_winhttp_openssl.cpp
// Single-file C++ (Windows) that:
// - Uses WinHTTP for HTTPS GET/POST with robust error handling
// - Downloads a Tor consensus document from a provided HTTPS URL and parses basic fields
// - Downloads a Tor v3 hidden-service descriptor from a provided HTTPS URL and parses basic fields
// - Validates and decodes a v3 .onion address (base32 -> pubkey/checksum/version) using OpenSSL SHA3-256
// - Demonstrates GET/POST over WinHTTP
//
// Build (MSVC):
//   cl /std:c++17 /O2 /EHsc tor_client_winhttp_openssl.cpp winhttp.lib crypt32.lib
//
// Command-line:
//   --consensus-url <https-url>
//   --descriptor-url <https-url>
//   --get <https-url>
//   --post <https-url> <body>
//   --onion-check <v3-onion-name>
//
// Note: This code provides networking, parsing, and cryptographic utilities requested,
// but does not implement Tor's relay/circuit protocol stack.

#define UNICODE
#define _UNICODE
#include <windows.h>
#include <winhttp.h>
