// -------------------- Utility: UTF conversions --------------------
static std::wstring Utf8ToWide(const std::string& s) {
    if (s.empty()) return L"";
    int len = MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), nullptr, 0);
    std::wstring out(len, 0);
    MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), &out[0], len);
    return out;
}
static std::string WideToUtf8(const std::wstring& ws) {
    if (ws.empty()) return "";
    int len = WideCharToMultiByte(CP_UTF8, 0, ws.c_str(), (int)ws.size(), nullptr, 0, nullptr, nullptr);
    std::string out(len, 0);
    WideCharToMultiByte(CP_UTF8, 0, ws.c_str(), (int)ws.size(), &out[0], len, nullptr, nullptr);
    return out;
}

// -------------------- Error helpers --------------------
static std::wstring FormatWinHttpError(DWORD err) {
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_FROM_HMODULE | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
                               GetModuleHandleW(L"winhttp.dll"), err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown WinHTTP error)";
    if (buf) LocalFree(buf);
    return s;
}
static std::wstring FormatLastError() {
    DWORD err = GetLastError();
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
                               nullptr, err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown error)";
    if (buf) LocalFree(buf);
    return s;
}
static std::string OpenSslErrStr() {
    BIO* bio = BIO_new(BIO_s_mem());
    if (!bio) return "BIO_new failed";
    ERR_print_errors(bio);
    BUF_MEM* mem = nullptr;
    BIO_get_mem_ptr(bio, &mem);
    std::string out = mem && mem->data ? std::string(mem->data, mem->length) : "";
    BIO_free(bio);
    return out;
}

// -------------------- RAII handles --------------------
struct WinHttpHandle {
    HINTERNET h{nullptr};
    WinHttpHandle() = default;
    explicit WinHttpHandle(HINTERNET handle) : h(handle) {}
    ~WinHttpHandle() { if (h) WinHttpCloseHandle(h); }
    WinHttpHandle(const WinHttpHandle&) = delete;
    WinHttpHandle& operator=(const WinHttpHandle&) = delete;
    WinHttpHandle(WinHttpHandle&& o) noexcept : h(o.h) { o.h = nullptr; }
    WinHttpHandle& operator=(WinHttpHandle&& o) noexcept {
        if (this != &o) {
            if (h) WinHttpCloseHandle(h);
            h = o.h; o.h = nullptr;
        }
        return *this;
    }
    operator HINTERNET() const { return h; }
};

// -------------------- URL parsing --------------------
struct ParsedUrl {
    std::wstring host;
    std::wstring path;
    INTERNET_PORT port{0};
    bool https{false};
};

static bool CrackUrl(const std::wstring& url, ParsedUrl& out) {
    URL_COMPONENTSW uc{};
    wchar_t host[1024]{};
    wchar_t path[4096]{};
    uc.dwStructSize = sizeof(uc);
    uc.lpszHostName = host; uc.dwHostNameLength = ARRAYSIZE(host);
    uc.lpszUrlPath = path; uc.dwUrlPathLength = ARRAYSIZE(path);
    uc.dwSchemeLength = (DWORD)-1;
    if (!WinHttpCrackUrl(url.c_str(), 0, 0, &uc)) {
        std::wcerr << L"WinHttpCrackUrl failed: " << FormatLastError() << L"\n";
        return false;
    }
    out.host.assign(uc.lpszHostName, uc.dwHostNameLength);
    out.path.clear();
    if (uc.lpszUrlPath && uc.dwUrlPathLength) out.path.append(uc.lpszUrlPath, uc.dwUrlPathLength);
    if (uc.lpszExtraInfo && uc.dwExtraInfoLength) out.path.append(uc.lpszExtraInfo, uc.dwExtraInfoLength);
    if (out.path.empty()) out.path = L"/";
    out.port = uc.nPort;
    out.https = (uc.nScheme == INTERNET_SCHEME_HTTPS);
    return true;
}

// -------------------- WinHTTP request --------------------
static bool HttpRequest(const std::wstring& url,
                        const std::wstring& method,
                        const std::wstring& headers,
                        const std::string& body,
                        DWORD& outStatus,
                        std::string& outRespBody,
                        std::wstring& outErr) {
    outStatus = 0;
    outRespBody.clear();
    outErr.clear();

    ParsedUrl pu{};
    if (!CrackUrl(url, pu)) {
        outErr = L"Invalid URL";
        return false;
    }

    WinHttpHandle sess(WinHttpOpen(L"tor-winhttp-openssl/1.0",
                                   WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                   WINHTTP_NO_PROXY_NAME,
                                   WINHTTP_NO_PROXY_BYPASS, 0));
    if (!sess.h) {
        outErr = L"WinHttpOpen failed: " + FormatLastError();
        return false;
    }

    DWORD flags = 0;
    if (pu.https) flags |= WINHTTP_FLAG_SECURE;

    WinHttpHandle conn(WinHttpConnect(sess.h, pu.host.c_str(), pu.port ? pu.port : (pu.https ? INTERNET_DEFAULT_HTTPS_PORT : INTERNET_DEFAULT_HTTP_PORT), 0));
    if (!conn.h) {
        outErr = L"WinHttpConnect failed: " + FormatLastError();
        return false;
    }

    WinHttpHandle req(WinHttpOpenRequest(conn.h,
                                         method.c_str(),
                                         pu.path.c_str(),
                                         nullptr,
                                         WINHTTP_NO_REFERER,
                                         WINHTTP_DEFAULT_ACCEPT_TYPES,
                                         flags));
    if (!req.h) {
        outErr = L"WinHttpOpenRequest failed: " + FormatLastError();
        return false;
    }

    // TLS options: enable modern settings (optional tuning)
    if (pu.https) {
        DWORD opt = WINHTTP_OPTION_SECURE_PROTOCOLS;
        DWORD val = WINHTTP_FLAG_SECURE_PROTOCOL_TLS1_2 | WINHTTP_FLAG_SECURE_PROTOCOL_TLS1_3;
        WinHttpSetOption(req.h, opt, &val, sizeof(val));
        DWORD secFlags = SECURITY_FLAG_IGNORE_UNKNOWN_CA; // keep strict defaults (no ignore) unless customized.
        (void)secFlags; // not enabling loosened checks.
    }

    BOOL ok = TRUE;
    if (!headers.empty()) {
        ok = WinHttpAddRequestHeaders(req.h, headers.c_str(), (DWORD)-1L, WINHTTP_ADDREQ_FLAG_ADD);
        if (!ok) {
            outErr = L"WinHttpAddRequestHeaders failed: " + FormatLastError();
            return false;
        }
    }

    LPCVOID pBody = body.empty() ? WINHTTP_NO_REQUEST_DATA : (LPCVOID)body.data();
    DWORD cbBody = body.empty() ? 0 : (DWORD)body.size();

    ok = WinHttpSendRequest(req.h,
                            WINHTTP_NO_ADDITIONAL_HEADERS,
                            0,
                            (LPVOID)pBody,
                            cbBody,
                            cbBody,
                            0);
    if (!ok) {
        outErr = L"WinHttpSendRequest failed: " + FormatLastError();
        return false;
    }

    ok = WinHttpReceiveResponse(req.h, nullptr);
    if (!ok) {
        outErr = L"WinHttpReceiveResponse failed: " + FormatLastError();
        return false;
    }

    // Status code
    DWORD status = 0; DWORD statusSize = sizeof(status);
    ok = WinHttpQueryHeaders(req.h, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &status, &statusSize, WINHTTP_NO_HEADER_INDEX);
    if (!ok) {
        outErr = L"WinHttpQueryHeaders(STATUS) failed: " + FormatLastError();
        return false;
    }
    outStatus = status;

    // Read body
    std::string buf;
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(req.h, &avail)) {
            outErr = L"WinHttpQueryDataAvailable failed: " + FormatLastError();
            return false;
        }
        if (!avail) break;
        std::string chunk(avail, '\0');
        DWORD read = 0;
        if (!WinHttpReadData(req.h, &chunk[0], avail, &read)) {
            outErr = L"WinHttpReadData failed: " + FormatLastError();
            return false;
        }
        chunk.resize(read);
        buf.append(chunk);
    }
    outRespBody.swap(buf);
    return true;
}

// -------------------- Base32 (RFC4648, lowercase a-z2-7) --------------------
static bool Base32DecodeLowerNoPadding(const std::string& in, std::vector<uint8_t>& out) {
    static const int8_t map[256] = {
        /* 0..255 init */ -1
    };
    static bool init = false;
    static int8_t m2[256];
    if (!init) {
        std::fill(std::begin(m2), std::end(m2), -1);
        const std::string alpha = "abcdefghijklmnopqrstuvwxyz234567";
        for (size_t i = 0; i < alpha.size(); ++i) m2[(unsigned char)alpha[i]] = (int8_t)i;
        for (size_t i = 0; i < alpha.size(); ++i) m2[(unsigned char)std::toupper(alpha[i])] = (int8_t)i;
        init = true;
    }
    uint32_t buffer = 0; int bitsLeft = 0;
    out.clear(); out.reserve(in.size() * 5 / 8);
    for (unsigned char c : in) {
        if (c == '=') break;
        int8_t v = m2[c];
        if (v < 0) return false;
        buffer = (buffer << 5) | (uint32_t)v;
        bitsLeft += 5;
        if (bitsLeft >= 8) {
            bitsLeft -= 8;
            out.push_back((uint8_t)((buffer >> bitsLeft) & 0xFF));
        }
    }
    return true;
}

// -------------------- Onion v3 validator --------------------
struct OnionV3Parts {
    std::array<uint8_t, 32> pubkey{};
    std::array<uint8_t, 2> checksum{};
    uint8_t version{3};
};

static bool ValidateOnionV3(const std::string& onion, OnionV3Parts& parts) {
    std::string name = onion;
    auto pos = name.find(".onion");
    if (pos != std::string::npos) name = name.substr(0, pos);
    if (name.size() != 56) return false;
    std::vector<uint8_t> decoded;
    if (!Base32DecodeLowerNoPadding(name, decoded)) return false;
    if (decoded.size() != 35) return false;
    std::copy(decoded.begin(), decoded.begin() + 32, parts.pubkey.begin());
    parts.checksum[0] = decoded[32];
    parts.checksum[1] = decoded[33];
    parts.version = decoded[34];
    if (parts.version != 3) return false;

    // checksum = first two bytes of SHA3-256(".onion checksum" || pubkey || version)
    static const uint8_t prefix[] = {'.','o','n','i','o','n',' ','c','h','e','c','k','s','u','m'};
    uint8_t msg[sizeof(prefix) + 32 + 1];
    memcpy(msg, prefix, sizeof(prefix));
    memcpy(msg + sizeof(prefix), parts.pubkey.data(), 32);
    msg[sizeof(prefix) + 32] = 0x03;

    uint8_t digest[32];
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) return false;
    bool ok = EVP_DigestInit_ex(ctx, EVP_sha3_256(), nullptr) == 1
           && EVP_DigestUpdate(ctx, msg, sizeof(msg)) == 1
           && EVP_DigestFinal_ex(ctx, digest, nullptr) == 1;
    EVP_MD_CTX_free(ctx);
    if (!ok) return false;

    return parts.checksum[0] == digest[0] && parts.checksum[1] == digest[1];
}

// -------------------- Simple parsing for Tor consensus --------------------
struct RelayInfo {
    std::string nickname;
    std::string fingerprint;
    std::string address;
    uint16_t or_port{0};
};
static std::vector<RelayInfo> ParseConsensus(const std::string& text) {
    std::vector<RelayInfo> relays;
    std::istringstream iss(text);
    std::string line;
    RelayInfo cur{};
    bool haveR = false;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.rfind("r ", 0) == 0) {
            if (haveR) relays.push_back(cur);
            cur = RelayInfo{};
            haveR = true;
            // r Nickname Identity Digest Publication IP ORPort DirPort
            // Nickname and IP and ORPort are present
            std::istringstream ls(line.substr(2));
            ls >> cur.nickname;
            std::string identity_b64, digest_b64, pub;
            ls >> identity_b64 >> digest_b64 >> pub >> cur.address;
            int orp = 0, dirp = 0;
            ls >> orp >> dirp;
            cur.or_port = (uint16_t)std::max(0, std::min(65535, orp));
        } else if (line.rfind("s ", 0) == 0) {
            // flags (ignored)
        } else if (line.rfind("v ", 0) == 0) {
            // version (ignored)
        } else if (line.rfind("w ", 0) == 0) {
            // bandwidth (ignored)
        } else if (line.empty() && haveR) {
            relays.push_back(cur);
            haveR = false;
        }
    }
    if (haveR) relays.push_back(cur);
    return relays;
}

// -------------------- Simple parsing for HS descriptor (v3) --------------------
struct HSDescriptor {
    std::string desc_id;
    std::string blinded_key_b64;
    std::vector<std::string> intro_points_b64;
};
static HSDescriptor ParseHSDescriptor(const std::string& text) {
    HSDescriptor d;
    std::istringstream iss(text);
    std::string line;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.rfind("hs-descriptor 3", 0) == 0) {
            // marker
        } else if (line.rfind("descriptor-signing-key-cert", 0) == 0) {
            // cert block to follow (ignored)
        } else if (line.rfind("desc-id ", 0) == 0) {
            d.desc_id = line.substr(strlen("desc-id "));
        } else if (line.rfind("blinded-key ", 0) == 0) {
            // next lines contain the key in PEM-like block; for demo, record line
            d.blinded_key_b64 = line.substr(strlen("blinded-key "));
        } else if (line.rfind("introduction-point ", 0) == 0) {
            d.intro_points_b64.push_back(line.substr(strlen("introduction-point ")));
        }
    }
    return d;
}

// -------------------- High-level helpers --------------------
static bool HttpGet(const std::wstring& url, std::string& body, DWORD& status, std::wstring& err) {
    std::wstring headers = L"Accept: */*\r\nUser-Agent: tor-winhttp-openssl/1.0\r\n";
    return HttpRequest(url, L"GET", headers, "", status, body, err);
}
static bool HttpPost(const std::wstring& url, const std::string& postBody, std::string& body, DWORD& status, std::wstring& err) {
    std::wstring headers = L"Accept: */*\r\nUser-Agent: tor-winhttp-openssl/1.0\r\nContent-Type: application/x-www-form-urlencoded\r\n";
    return HttpRequest(url, L"POST", headers, postBody, status, body, err);
}

// -------------------- CLI --------------------
static void PrintUsage() {
    std::wcout
        << L"Options:\n"
        << L"  --consensus-url <https-url>\n"
        << L"  --descriptor-url <https-url>\n"
        << L"  --get <https-url>\n"
        << L"  --post <https-url> <body>\n"
        << L"  --onion-check <v3-onion-name>\n";
}

int wmain(int argc, wchar_t** argv) {
    ERR_load_crypto_strings();
    OpenSSL_add_all_algorithms();

    std::map<std::wstring, std::vector<std::wstring>> args;
    for (int i = 1; i < argc; ++i) {
        std::wstring k = argv[i];
        if (k.rfind(L"--", 0) == 0) {
            std::vector<std::wstring> vals;
            // Collect following tokens that are not options
            int j = i + 1;
            while (j < argc && std::wstring(argv[j]).rfind(L"--", 0) != 0) {
                vals.push_back(argv[j]); ++j;
            }
            args.emplace(k, vals);
            i = j - 1;
        }
    }

    bool didSomething = false;

    // GET
    if (auto it = args.find(L"--get"); it != args.end() && !it->second.empty()) {
        const std::wstring url = it->second[0];
        std::string body; DWORD status = 0; std::wstring err;
        if (!HttpGet(url, body, status, err)) {
            std::wcerr << L"GET failed: " << err << L"\n";
            return 1;
        }
        std::wcout << L"GET status: " << status << L"\n";
        std::wcout << Utf8ToWide(body) << L"\n";
        didSomething = true;
    }

    // POST
    if (auto it = args.find(L"--post"); it != args.end() && it->second.size() >= 2) {
        const std::wstring url = it->second[0];
        const std::wstring wbody = it->second[1];
        std::string body; DWORD status = 0; std::wstring err;
        if (!HttpPost(url, WideToUtf8(wbody), body, status, err)) {
            std::wcerr << L"POST failed: " << err << L"\n";
            return 1;
        }
        std::wcout << L"POST status: " << status << L"\n";
        std::wcout << Utf8ToWide(body) << L"\n";
        didSomething = true;
    }

    // Consensus
    if (auto it = args.find(L"--consensus-url"); it != args.end() && !it->second.empty()) {
        const std::wstring url = it->second[0];
        std::string body; DWORD status = 0; std::wstring err;
        if (!HttpGet(url, body, status, err)) {
            std::wcerr << L"Consensus download failed: " << err << L"\n";
            return 1;
        }
        std::wcout << L"Consensus HTTP status: " << status << L"\n";
        auto relays = ParseConsensus(body);
        std::wcout << L"Parsed relays: " << relays.size() << L"\n";
        if (!relays.empty()) {
            std::wcout << L"Example relay: " << Utf8ToWide(relays[0].nickname)
                       << L" " << Utf8ToWide(relays[0].address)
                       << L":" << relays[0].or_port << L"\n";
        }
        didSomething = true;
    }

    // HS descriptor
    if (auto it = args.find(L"--descriptor-url"); it != args.end() && !it->second.empty()) {
        const std::wstring url = it->second[0];
        std::string body; DWORD status = 0; std::wstring err;
        if (!HttpGet(url, body, status, err)) {
            std::wcerr << L"Descriptor download failed: " << err << L"\n";
            return 1;
        }
        std::wcout << L"Descriptor HTTP status: " << status << L"\n";
        auto d = ParseHSDescriptor(body);
        std::wcout << L"Descriptor ID: " << Utf8ToWide(d.desc_id) << L"\n";
        std::wcout << L"Blinded key (raw line): " << Utf8ToWide(d.blinded_key_b64) << L"\n";
        std::wcout << L"Introduction points: " << d.intro_points_b64.size() << L"\n";
        didSomething = true;
    }

    // Onion address check
    if (auto it = args.find(L"--onion-check"); it != args.end() && !it->second.empty()) {
        const std::string onion = WideToUtf8(it->second[0]);
        OnionV3Parts p{};
        bool ok = ValidateOnionV3(onion, p);
        std::wcout << L"Onion v3 validate: " << (ok ? L"OK" : L"FAIL") << L"\n";
        if (ok) {
            std::wcout << L"Pubkey[0..3]: ";
            for (int i = 0; i < 4; ++i) std::wcout << std::hex << std::setw(2) << std::setfill(L'0') << (int)p.pubkey[i];
            std::wcout << std::dec << L"\n";
        }
        didSomething = true;
    }

    if (!didSomething) {
        PrintUsage();
    }

    EVP_cleanup();
    ERR_free_strings();
    return 0;
}

