  ArraySetAsSeries(bufRSI,  true);
  ArraySetAsSeries(bufATR,  true);

  if(CopyBuffer(hFastEMA, 0, 0, need, bufFast) < need) { LogLastError("CopyBuffer fast EMA"); return false; }
  if(CopyBuffer(hSlowEMA, 0, 0, need, bufSlow) < need) { LogLastError("CopyBuffer slow EMA"); return false; }
  if(CopyBuffer(hRSI,     0, 0, need, bufRSI)  < need) { LogLastError("CopyBuffer RSI"); return false; }
  if(CopyBuffer(hATR,     0, 0, need, bufATR)  < need) { LogLastError("CopyBuffer ATR"); return false; }

  MqlRates rates[3];
  ArraySetAsSeries(rates, true);
  if(CopyRates(gSymbol, InpTimeframe, 0, need, rates) < need) { LogLastError("CopyRates"); return false; }

  emaFastCur = bufFast[0];
  emaSlowCur = bufSlow[0];
  rsiCur     = bufRSI[0];
  atrCur     = bufATR[0];

  emaFastPrev= bufFast[1];
  emaSlowPrev= bufSlow[1];
  rsiPrev    = bufRSI[1];

  barTime = rates[0].time;
  return true;
}

struct Signal
{
  int direction;   // 1=buy, -1=sell, 0=none
  double sl;       // price
  double tp;       // price
};

Signal GenerateSignal()
{
  Signal s; s.direction=0; s.sl=0; s.tp=0;

  double emaFastCur, emaSlowCur, rsiCur, atrCur, emaFastPrev, emaSlowPrev, rsiPrev;
  datetime barTime;
  if(!GetLatestIndicatorValues(emaFastCur, emaSlowCur, rsiCur, atrCur, emaFastPrev, emaSlowPrev, rsiPrev, barTime))
    return s;

  if(InpOnlyNewBarSignals && gLastSignalBarTime == barTime)
    return s;

  if(InpATR_MinFilter > 0 && atrCur < InpATR_MinFilter)
    return s;

  // Cross detection
  bool bullCross = (emaFastPrev <= emaSlowPrev) && (emaFastCur > emaSlowCur);
  bool bearCross = (emaFastPrev >= emaSlowPrev) && (emaFastCur < emaSlowCur);

  // RSI filter
  bool rsiBull = rsiCur >= InpRSI_Buy;
  bool rsiBear = rsiCur <= InpRSI_Sell;

  double bid, ask;
  if(!GetMarketPrices(bid, ask)) return s;

  if(bullCross && rsiBull)
  {
    double sl = bid - InpATR_SL_Mult * atrCur;
    double tp = bid + InpRR * (bid - sl);
    s.direction = 1;
    s.sl = sl;
    s.tp = tp;
    gLastSignalBarTime = barTime;
  }
  else if(bearCross && rsiBear)
  {
    double sl = ask + InpATR_SL_Mult * atrCur;
    double tp = ask - InpRR * (sl - ask);
    s.direction = -1;
    s.sl = sl;
    s.tp = tp;
    gLastSignalBarTime = barTime;
  }

  return s;
}

bool RespectStopsLevels(double &sl, double &tp, const int dir)
{
  double bid, ask;
  if(!GetMarketPrices(bid, ask)) return false;

  double minStop = PointsToPrice(gStopsLevelPoints);
  double freeze  = PointsToPrice(gFreezeLevelPoints);

  if(dir==1) // buy
  {
    if(sl>0 && (bid - sl) < minStop) sl = bid - minStop;
    if(tp>0 && (tp - bid) < minStop) tp = bid + minStop;
    // avoid freeze by not modifying too close on entry; handled by deviation later
  }
  else if(dir==-1) // sell
  {
    if(sl>0 && (sl - ask) < minStop) sl = ask + minStop;
    if(tp>0 && (ask - tp) < minStop) tp = ask - minStop;
  }
  return true;
}

double ProjectedMarginLevelPct(double equity, double free_margin, double add_margin)
{
  double used_margin = AccountInfoDouble(ACCOUNT_MARGIN) + add_margin;
  if(used_margin <= 0.0) return 999999.0;
  return (equity / used_margin) * 100.0;
}

bool CalcVolumeByRisk(const int dir, const double sl_price, double &volume, double &est_margin)
{
  volume = 0.0;
  est_margin = 0.0;

  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(equity<=0 || free_margin<=0){ Print("Equity or FreeMargin <= 0"); return false; }

  double bid, ask;
  if(!GetMarketPrices(bid, ask)) return false;

  double entry = (dir==1? ask : bid);
  double stop_distance = MathAbs(entry - sl_price);
  if(stop_distance <= 0)
  {
    Print("Invalid stop distance");
    return false;
  }

  // Risk amount in deposit currency
  double risk_amt = equity * (InpRiskPerTradePct/100.0);
  if(risk_amt <= 0){ Print("Risk amount <= 0"); return false; }

  // Tick value and size
  if(gTickValue<=0 || gTickSize<=0){ Print("Tick parameters invalid"); return false; }

  // Profit per point per lot in deposit currency:
  // value_per_point_per_lot = TickValue * (Point / TickSize)
  double value_per_point_per_lot = gTickValue * (gPoint / gTickSize);
  if(value_per_point_per_lot<=0){ Print("value_per_point_per_lot invalid"); return false; }

  double stop_points = stop_distance / gPoint;
  double loss_per_lot = stop_points * value_per_point_per_lot;

  if(loss_per_lot <= 0){ Print("Computed loss_per_lot <= 0"); return false; }

  double raw_lots = risk_amt / loss_per_lot;
  if(raw_lots <= 0){ Print("Risk sizing produced nonpositive lots"); return false; }

  // Respect broker limits
  double lots = NormalizeVolume(raw_lots);

  // Check margin usage via OrderCalcMargin and per-trade cap
  double price = entry;
  double margin = 0.0;
  ENUM_ORDER_TYPE ord_type = (dir==1? ORDER_TYPE_BUY : ORDER_TYPE_SELL);
  if(!OrderCalcMargin(ord_type, gSymbol, lots, price, margin))
  {
    LogLastError("OrderCalcMargin failed");
    return false;
  }

  // Cap margin to percentage of free margin
  double max_margin_allowed = free_margin * (InpMaxFreeMarginUsagePct/100.0);
  if(max_margin_allowed <= 0){ Print("Max margin allowed <= 0"); return false; }

  if(margin > max_margin_allowed && margin > 0.0)
  {
    // scale lots down proportionally
    double scale = max_margin_allowed / margin;
    lots = NormalizeVolume(lots * scale);
    if(lots < gMinVolume) { Print("Lots after margin cap < minimum."); return false; }

    if(!OrderCalcMargin(ord_type, gSymbol, lots, price, margin))
    {
      LogLastError("OrderCalcMargin after cap failed");
      return false;
    }
  }

  // Sanity: ensure free margin can cover it and margin level threshold is respected
  if(margin >= free_margin)
  {
    PrintFormat("Insufficient free margin. Need=%.2f, Free=%.2f", margin, free_margin);
    return false;
  }

  double equity_after = equity; // no immediate change to equity on entry
  double proj_level = ProjectedMarginLevelPct(equity_after, free_margin, margin);
  if(InpMinMarginLevelPct > 0.0 && proj_level < InpMinMarginLevelPct)
  {
    PrintFormat("Projected margin level %.2f%% would fall below threshold %.2f%%", proj_level, InpMinMarginLevelPct);
    return false;
  }

  volume = lots;
  est_margin = margin;
  return true;
}

bool PlaceOrder(const int dir, double sl, double tp, ulong &order_ticket)
{
  order_ticket = 0;

  double bid, ask;
  if(!GetMarketPrices(bid, ask)) return false;

  if(!RespectStopsLevels(sl, tp, dir)) return false;

  double volume, est_margin;
  if(!CalcVolumeByRisk(dir, sl, volume, est_margin))
    return false;

  MqlTradeRequest  req;
  MqlTradeResult   res;
  ZeroMemory(req);
  ZeroMemory(res);

  req.action   = TRADE_ACTION_DEAL;
  req.symbol   = gSymbol;
  req.magic    = InpMagicNumber;
  req.type     = (dir==1? ORDER_TYPE_BUY : ORDER_TYPE_SELL);
  req.volume   = volume;
  req.deviation= InpSlippagePoints;
  req.type_filling = ORDER_FILLING_FOK;

  if(dir==1)
  {
    req.price = ask;
    req.sl    = sl;
    req.tp    = tp;
  }
  else
  {
    req.price = bid;
    req.sl    = sl;
    req.tp    = tp;
  }

  if(!OrderSend(req, res))
  {
    LogLastError("OrderSend failed");
    return false;
  }
  if(res.retcode != TRADE_RETCODE_DONE && res.retcode != TRADE_RETCODE_PLACED)
  {
    PrintFormat("OrderSend retcode=%d description=%s", (int)res.retcode, res.comment);
    return false;
  }

  order_ticket = res.order;
  PrintFormat("Order placed: dir=%s lots=%.2f SL=%.5f TP=%.5f ticket=%I64u",
              (dir==1?"BUY":"SELL"), volume, sl, tp, order_ticket);
  return true;
}

void ManagePositionTrailing()
{
  if(!InpAllowTrailing) return;

  for(int i=0;i<PositionsTotal();i++)
  {
    if(!PositionSelectByTicket(PositionGetTicket(i))) continue;
    if(PositionGetString(POSITION_SYMBOL)!=gSymbol) continue;
    if((ulong)PositionGetInteger(POSITION_MAGIC)!=InpMagicNumber) continue;

    int type = (int)PositionGetInteger(POSITION_TYPE);
    double price_open = PositionGetDouble(POSITION_PRICE_OPEN);
    double sl = PositionGetDouble(POSITION_SL);
    double tp = PositionGetDouble(POSITION_TP);
    double volume = PositionGetDouble(POSITION_VOLUME);
    double bid, ask;
    if(!GetMarketPrices(bid, ask)) return;

    // Compute ATR-based trail distance
    double atrCur[1];
    if(CopyBuffer(hATR, 0, 0, 1, atrCur) < 1) { LogLastError("CopyBuffer ATR (trailing)"); return; }
    double trail_dist = InpATR_TrailMult * atrCur[0];

    // Breakeven
    double rr_for_be = InpBreakevenRR;
    if(rr_for_be > 0.0)
    {
      double risk_per_unit = (type==POSITION_TYPE_BUY ? (price_open - sl) : (sl - price_open));
      if(risk_per_unit > 0.0)
      {
        double gain = (type==POSITION_TYPE_BUY ? (bid - price_open) : (price_open - ask));
        double rr = gain / risk_per_unit;
        if(rr >= rr_for_be)
        {
          double be = price_open;
          if(type==POSITION_TYPE_BUY)
            sl = MathMax(sl, be);
          else
            sl = MathMin(sl, be);
        }
      }
    }

    bool need_modify = false;
    if(type==POSITION_TYPE_BUY)
    {
      double desired_sl = bid - trail_dist;
      if(sl==0 || desired_sl - sl > PointsToPrice(1)) // move only if improves
      {
        // Respect stops level
        double minStop = PointsToPrice(gStopsLevelPoints);
        if((bid - desired_sl) < minStop) desired_sl = bid - minStop;
        if(desired_sl > sl)
        {
          sl = desired_sl;
          need_modify = true;
        }
      }
    }
    else if(type==POSITION_TYPE_SELL)
    {
      double desired_sl = ask + trail_dist;
      if(sl==0 || sl - desired_sl > PointsToPrice(1))
      {
        double minStop = PointsToPrice(gStopsLevelPoints);
        if((desired_sl - ask) < minStop) desired_sl = ask + minStop;
        if(desired_sl < sl || sl==0.0)
        {
          sl = desired_sl;
          need_modify = true;
        }
      }
    }

    if(need_modify)
    {
      trade.SetExpertMagicNumber(InpMagicNumber);
      if(!trade.PositionModify(gSymbol, sl, tp))
      {
        LogLastError("PositionModify (trailing) failed");
      }
      else
      {
        PrintFormat("Trailing SL modified: symbol=%s sl=%.5f tp=%.5f", gSymbol, sl, tp);
      }
    }
  }
}

