//------------------------------------------------------------------
int OnInit()
{
  ResetLastError();

  if(!RefreshSymbolInfo(_Symbol)) { return INIT_FAILED; }
  ParseSkipHours(InpSkipHoursUTC);

  if(!LoadIndicatorHandles()) { return INIT_FAILED; }

  // Preload buffers
  double dummy;
  datetime bt;
  double a,b,c,d,e,f,g;
  if(!GetLatestIndicatorValues(a,b,c,d,e,f,g,bt))
  {
    Print("Indicators not ready");
    return INIT_FAILED;
  }

  trade.SetExpertMagicNumber(InpMagicNumber);
  Print("EA initialized on ", gSymbol, " TF=", EnumToString(InpTimeframe));
  return INIT_SUCCEEDED;
}

void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI    !=INVALID_HANDLE) IndicatorRelease(hRSI);
  if(hATR    !=INVALID_HANDLE) IndicatorRelease(hATR);
}

void OnTick()
{
  if(_Symbol != gSymbol)
  {
    if(!RefreshSymbolInfo(_Symbol)) return;
  }

  // Filters
  if(IsSessionBlocked()) return;
  if(!IsSpreadOK()) return;

  // Enforce one-position-per-symbol
  int pos_dir; ulong pos_ticket;
  bool have_pos = HaveOpenPositionForSymbol(pos_dir, pos_ticket);

  // Manage existing
  if(have_pos) ManagePositionTrailing();

  // Entry logic only if no position
  if(!have_pos)
  {
    Signal sig = GenerateSignal();
    if(sig.direction != 0)
    {
      ulong ticket;
      if(!PlaceOrder(sig.direction, sig.sl, sig.tp, ticket))
      {
        // error already logged
      }
    }
  }
}

//+------------------------------------------------------------------+
//|                                       EMA_RSI_ATR_Manager.mq5    |
//|   EMA Cross + RSI + ATR with robust risk & margin management     |
//|   One-position-per-symbol, spread/session filters, trailing SL   |
//+------------------------------------------------------------------+
#property strict
#property version   "1.30"
#property description "EMA Cross + RSI + ATR strategy with complete trade management and robust margin/risk logic."

#include <Trade/Trade.mqh>

CTrade trade;

//========================
// Inputs: Strategy & Risk
//========================
input ENUM_TIMEFRAMES InpTimeframe      = PERIOD_M5;      // Signal timeframe
input int             InpFastEMA        = 21;             // Fast EMA period
input int             InpSlowEMA        = 55;             // Slow EMA period
input int             InpRSIPeriod      = 14;             // RSI period
input double          InpRSI_Buy        = 55.0;           // RSI threshold for buys
input double          InpRSI_Sell       = 45.0;           // RSI threshold for sells
input int             InpATRPeriod      = 14;             // ATR period
input double          InpATR_SL_Mult    = 1.5;            // SL = ATR * this multiplier
input double          InpATR_TrailMult  = 1.0;            // Trailing distance = ATR * this multiplier
input double          InpRR             = 2.0;            // Reward:Risk ratio
input double          InpATR_MinFilter  = 0.0;            // Minimum ATR filter (price units); set 0 to disable

//========================
// Inputs: Risk Management
//========================
input double          InpRiskPerTradePct          = 0.5;    // Percent of equity to risk per trade
input double          InpMaxFreeMarginUsagePct     = 10.0;   // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct         = 500.0;  // Block entries if margin level below this (%); <=0 to ignore
input ulong           InpMagicNumber               = 987654321; // Magic number to tag positions

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints            = 20;     // Max deviation (points)
input int             InpMaxSpreadPoints           = 30;     // Max spread (points) allowed for entries
input string          InpSkipHoursUTC              = "21,22";// Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing             = true;   // Enable trailing SL
input double          InpBreakevenRR               = 1.0;    // Move SL to BE after reaching this RR (0 to disable)

//========================
// Internal state & handles
//========================
int     hFastEMA = INVALID_HANDLE;
int     hSlowEMA = INVALID_HANDLE;
int     hRSI     = INVALID_HANDLE;
int     hATR     = INVALID_HANDLE;

datetime gLastSignalBarTime = 0;

// Symbol parameters cache
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC)
bool    gSkipHour[24];

//----------------------------------------------
// Utility: Parse skip hours string to bool map
//----------------------------------------------
void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = hours_csv;
  StringTrimLeft(trimmed);
  StringTrimRight(trimmed);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = parts[i];
    StringTrimLeft(p);
    StringTrimRight(p);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

//----------------------------------------------
// Utility: Refresh and cache symbol trading info
//----------------------------------------------
bool RefreshSymbolInfo(const string sym)
{
  if(!SymbolInfoInteger(sym, SYMBOL_SELECT))
    SymbolSelect(sym, true);

  gPoint = SymbolInfoDouble(sym, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(sym, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_SIZE);
  gTickValue = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume = SymbolInfoDouble(sym, SYMBOL_VOLUME_MIN);
  gMaxVolume = SymbolInfoDouble(sym, SYMBOL_VOLUME_MAX);
  gVolStep = SymbolInfoDouble(sym, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_FREEZE_LEVEL);

  if(gPoint<=0 || gTickSize<=0 || gTickValue<=0 || gMinVolume<=0 || gVolStep<=0)
  {
    PrintFormat("Error: Invalid symbol info. point=%.10f ticksize=%.10f tickvalue=%.10f minvol=%.2f volstep=%.2f",
                gPoint, gTickSize, gTickValue, gMinVolume, gVolStep);
  }
  return (gPoint>0 && gTickSize>0 && gTickValue>0 && gMinVolume>0 && gVolStep>0);
}

//----------------------------------------------
// Utility: Normalize lot volume to broker step
//----------------------------------------------
double NormalizeVolume(double vol)
{
  if(vol<=0) return 0.0;
  // Align to step (round down to avoid rejection)
  double steps = MathFloor(vol / gVolStep + 1e-8);
  double v = steps * gVolStep;
  v = MathMin(MathMax(v, gMinVolume), gMaxVolume);
  // Use 2 decimals typical for FX; broker enforces step anyway
  return NormalizeDouble(v, (int)MathMax(0, (int)MathRound(-MathLog10(gVolStep))));
}

//----------------------------------------------
// Utility: Normalize price to symbol digits
//----------------------------------------------
double NormalizePrice(double price)
{
  return NormalizeDouble(price, gDigits);
}

//----------------------------------------------
// Utility: Spread filter (points)
//----------------------------------------------
bool SpreadOK(const string sym, int maxSpreadPoints)
{
  MqlTick tick;
  if(!SymbolInfoTick(sym, tick)) return false;
  double spreadPoints = (tick.ask - tick.bid) / gPoint;
  return (spreadPoints <= maxSpreadPoints);
}

//----------------------------------------------
// Utility: Check skip hour filter (UTC)
//----------------------------------------------
bool SessionOK()
{
  datetime now = TimeCurrent(); // server time (ideally UTC on most brokers)
  MqlDateTime dt;
  TimeToStruct(now, dt);
  int hourUTC = dt.hour; // assume server time UTC; adapt if broker offset differs
  if(hourUTC>=0 && hourUTC<24)
    return !gSkipHour[hourUTC];
  return true;
}

//----------------------------------------------
// Utility: One-position-per-symbol (strict)
//----------------------------------------------
bool HasAnyPositionOnSymbol(const string sym)
{
  int total = PositionsTotal();
  for(int i=0;i<total;i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    if(PositionGetString(POSITION_SYMBOL) == sym)
      return true;
  }
  return false;
}

bool GetOurPosition(const string sym, ulong &ticketOut, long &typeOut, double &priceOpenOut, double &slOut, double &tpOut, double &volumeOut)
{
  ticketOut = 0;
  typeOut = -1;
  slOut = 0; tpOut=0; volumeOut=0; priceOpenOut=0;
  int total = PositionsTotal();
  for(int i=0;i<total;i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    if(PositionGetString(POSITION_SYMBOL) != sym) continue;
    if((ulong)PositionGetInteger(POSITION_MAGIC) != InpMagicNumber) continue;

    ticketOut = (ulong)PositionGetInteger(POSITION_TICKET);
    typeOut   = (long)PositionGetInteger(POSITION_TYPE);
    priceOpenOut = PositionGetDouble(POSITION_PRICE_OPEN);
    slOut = PositionGetDouble(POSITION_SL);
    tpOut = PositionGetDouble(POSITION_TP);
    volumeOut = PositionGetDouble(POSITION_VOLUME);
    return true;
  }
  return false;
}

//----------------------------------------------
// Utility: Indicator setup
//----------------------------------------------
bool InitIndicators(const string sym, ENUM_TIMEFRAMES tf)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);

  hFastEMA = iMA(sym, tf, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  hSlowEMA = iMA(sym, tf, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  hRSI     = iRSI(sym, tf, InpRSIPeriod, PRICE_CLOSE);
  hATR     = iATR(sym, tf, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    Print("Error: Failed to create indicator handles. FastEMA=", hFastEMA,
          " SlowEMA=", hSlowEMA, " RSI=", hRSI, " ATR=", hATR);
    return false;
  }
  return true;
}

//----------------------------------------------
// Utility: Read indicator values on bar [shift]
//----------------------------------------------
bool ReadIndicators(const string sym, ENUM_TIMEFRAMES tf, int shift,
                    double &emaFast, double &emaSlow, double &rsi, double &atr)
{
  emaFast = emaSlow = rsi = atr = 0.0;

  double bufFast[2], bufSlow[2], bufRSI[2], bufATR[2];
  if(CopyBuffer(hFastEMA, 0, shift, 2, bufFast) < 2) return false;
  if(CopyBuffer(hSlowEMA, 0, shift, 2, bufSlow) < 2) return false;
  if(CopyBuffer(hRSI,     0, shift, 1, bufRSI) < 1) return false;
  if(CopyBuffer(hATR,     0, shift, 1, bufATR) < 1) return false;

  emaFast = bufFast[0];
  emaSlow = bufSlow[0];
  rsi     = bufRSI[0];
  atr     = bufATR[0];
  return (emaFast!=0 && emaSlow!=0 && atr!=0);
}

//----------------------------------------------
// Utility: Margin level percent
//----------------------------------------------
double CurrentMarginLevelPct()
{
  double margin = AccountInfoDouble(ACCOUNT_MARGIN);
  if(margin<=0.0) return -1.0;
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  if(margin==0.0) return -1.0;
  return (equity/margin)*100.0;
}

//----------------------------------------------
// Utility: Calculate risk-based volume with constraints
//----------------------------------------------
double CalculateVolumeByRisk(const string sym, ENUM_ORDER_TYPE type,
                             double entryPrice, double stopPrice,
                             double riskPct, double maxFreeMarginUsagePct,
                             double &estMarginOut)
{
  estMarginOut = 0.0;

  // Risk in account currency
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  if(equity<=0) return 0.0;
  double riskAmount = equity * (riskPct/100.0);
  if(riskAmount<=0) return 0.0;

  // Price distance to stop (absolute)
  double stopDist = MathAbs(entryPrice - stopPrice);
  if(stopDist <= 0) return 0.0;

  // Value per point per lot
  // Use SYMBOL_TRADE_TICK_VALUE and TICK_SIZE to derive per price-unit value
  double valuePerPriceUnitPerLot = 0.0;
  if(gTickSize>0.0 && gTickValue>0.0)
    valuePerPriceUnitPerLot = gTickValue / gTickSize;
  if(valuePerPriceUnitPerLot<=0) return 0.0;

  // Lot based on risk: riskAmount = stopDist * valuePerPriceUnitPerLot * lots
  double lotsByRisk = riskAmount / (stopDist * valuePerPriceUnitPerLot);
  if(lotsByRisk<=0) return 0.0;

  // Estimate margin for 1 lot, then scale
  double marginPerLot = 0.0;
  double volumeProbe = MathMax(gMinVolume, gVolStep);
  double price = entryPrice;
  if(!OrderCalcMargin(type, sym, volumeProbe, price, marginPerLot))
  {
    Print("Error: OrderCalcMargin probe failed. Code=", GetLastError());
    return 0.0;
  }
  if(volumeProbe>0) marginPerLot /= volumeProbe;

  // Free margin cap
  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  double marginCap = freeMargin * (maxFreeMarginUsagePct/100.0);
  if(marginPerLot>0)
  {
    double lotsByMarginCap = marginCap / marginPerLot;
    lotsByRisk = MathMin(lotsByRisk, lotsByMarginCap);
  }

  // Normalize to broker step and min/max
  double lots = NormalizeVolume(lotsByRisk);
  if(lots<gMinVolume) return 0.0;

  // Final estimated margin
  double estMargin=0.0;
  if(!OrderCalcMargin(type, sym, lots, price, estMargin))
  {
    Print("Error: OrderCalcMargin(final) failed. Code=", GetLastError());
    return 0.0;
  }
  estMarginOut = estMargin;
  return lots;
}

//----------------------------------------------
// Utility: Build SL/TP based on ATR and RR
//----------------------------------------------
bool BuildSLTP(const string sym, ENUM_POSITION_TYPE posType, double entry,
               double atr, double &slOut, double &tpOut)
{
  double slDist = InpATR_SL_Mult * atr;
  if(slDist <= 0) return false;

  if(posType == POSITION_TYPE_BUY)
  {
    slOut = NormalizePrice(entry - slDist);
    tpOut = NormalizePrice(entry + InpRR * slDist);
  }
  else if(posType == POSITION_TYPE_SELL)
  {
    slOut = NormalizePrice(entry + slDist);
    tpOut = NormalizePrice(entry - InpRR * slDist);
  }
  else return false;

  // Respect stops/freeze levels
  MqlTick tick;
  if(!SymbolInfoTick(sym, tick)) return false;
  double minStop = gStopsLevelPoints * gPoint;
  if(gStopsLevelPoints>0)
  {
    if(posType==POSITION_TYPE_BUY)
    {
      if((entry - slOut) < minStop) slOut = NormalizePrice(entry - minStop);
      if((tpOut - entry) < minStop) tpOut = NormalizePrice(entry + minStop);
    }
    else
    {
      if((slOut - entry) < minStop) slOut = NormalizePrice(entry + minStop);
      if((entry - tpOut) < minStop) tpOut = NormalizePrice(entry - minStop);
    }
  }
  return true;
}

//----------------------------------------------
// Utility: Trailing stop management
//----------------------------------------------
void ManageTrailing(const string sym, const double atr)
{
  ulong ticket; long type; double openPrice, sl, tp, vol;
  if(!GetOurPosition(sym, ticket, type, openPrice, sl, tp, vol)) return;

  MqlTick tick;
  if(!SymbolInfoTick(sym, tick)) return;

  double trailDist = InpATR_TrailMult * atr;
  if(trailDist <= 0) return;

  double newSL = sl;
  if(type == POSITION_TYPE_BUY)
  {
    double priceRef = tick.bid - trailDist;
    if(InpBreakevenRR > 0)
    {
      double slBase = openPrice; // breakeven
      double beTrigger = openPrice + InpBreakevenRR * (openPrice - (openPrice - InpATR_SL_Mult*atr));
      if(tick.bid >= beTrigger)
        priceRef = MathMax(priceRef, slBase);
    }
    if(sl <= 0 || priceRef > sl + gPoint) // update if better
      newSL = NormalizePrice(priceRef);
  }
  else if(type == POSITION_TYPE_SELL)
  {
    double priceRef = tick.ask + trailDist;
    if(InpBreakevenRR > 0)
    {
      double slBase = openPrice; // breakeven
      double beTrigger = openPrice - InpBreakevenRR * ((openPrice + InpATR_SL_Mult*atr) - openPrice);
      if(tick.ask <= beTrigger)
        priceRef = MathMin(priceRef, slBase);
    }
    if(sl <= 0 || priceRef < sl - gPoint)
      newSL = NormalizePrice(priceRef);
  }

  // Respect freeze level
  double freezeDist = gFreezeLevelPoints * gPoint;
  if(type == POSITION_TYPE_BUY && (tick.bid - newSL) < freezeDist) return;
  if(type == POSITION_TYPE_SELL && (newSL - tick.ask) < freezeDist) return;

  if(newSL != sl && newSL>0)
  {
    trade.SetMagic(InpMagicNumber);
    if(!trade.PositionModify(sym, newSL, tp))
    {
      Print("Warning: PositionModify (trail) failed. Code=", trade.ResultRetcode(), " ", trade.ResultRetcodeDescription());
    }
  }
}

//----------------------------------------------
// Signal generation: EMA cross + RSI + ATR filter
//----------------------------------------------
int GenerateSignal(const string sym, ENUM_TIMEFRAMES tf, double &atrOut)
{
  // Return: 1=buy, -1=sell, 0=none
  double emaFast0, emaSlow0, rsi0, atr0;
  double emaFast1, emaSlow1, rsi1, atr1;

  if(!ReadIndicators(sym, tf, 0, emaFast0, emaSlow0, rsi0, atr0)) return 0;
  if(!ReadIndicators(sym, tf, 1, emaFast1, emaSlow1, rsi1, atr1)) return 0;

  atrOut = atr0;
  if(InpATR_MinFilter > 0.0 && atr0 < InpATR_MinFilter) return 0;

  bool crossUp   = (emaFast1 <= emaSlow1) && (emaFast0 > emaSlow0);
  bool crossDown = (emaFast1 >= emaSlow1) && (emaFast0 < emaSlow0);

  if(crossUp && rsi0 >= InpRSI_Buy)   return 1;
  if(crossDown && rsi0 <= InpRSI_Sell) return -1;
  return 0;
}

//----------------------------------------------
// Entry checks: margin/risk/session/spread/one-position
//----------------------------------------------
bool PreEntryChecks(const string sym)
{
  if(!RefreshSymbolInfo(sym)) return false;
  if(!SpreadOK(sym, InpMaxSpreadPoints))
  {
    Print("Info: Spread filter blocks entry.");
    return false;
  }
  if(!SessionOK())
  {
    Print("Info: Session filter blocks entry (skip hour).");
    return false;
  }
  // Strict one-position-per-symbol rule: block if any position exists on this symbol
  if(HasAnyPositionOnSymbol(sym))
  {
    // No pyramiding or hedging on same symbol
    return false;
  }

  // Margin level check if available
  if(InpMinMarginLevelPct > 0)
  {
    double ml = CurrentMarginLevelPct();
    if(ml>0 && ml < InpMinMarginLevelPct)
    {
      PrintFormat("Info: Margin Level %.2f%% below threshold %.2f%%. Block entry.", ml, InpMinMarginLevelPct);
      return false;
    }
  }
  return true;
}

//----------------------------------------------
// Order placement with explicit error handling
//----------------------------------------------
bool PlaceOrderWithSLTP(const string sym, int signal, double atr)
{
  MqlTick tick;
  if(!SymbolInfoTick(sym, tick))
  {
    Print("Error: SymbolInfoTick failed.");
    return false;
  }

  ENUM_ORDER_TYPE type = (signal>0 ? ORDER_TYPE_BUY : ORDER_TYPE_SELL);
  double entry = (signal>0 ? tick.ask : tick.bid);

  // Build provisional SL/TP based on ATR
  double sl=0.0, tp=0.0;
  ENUM_POSITION_TYPE ptype = (signal>0 ? POSITION_TYPE_BUY : POSITION_TYPE_SELL);
  if(!BuildSLTP(sym, ptype, entry, atr, sl, tp))
  {
    Print("Error: BuildSLTP failed.");
    return false;
  }

  // Compute risk-based volume with per-trade margin cap
  double estMargin=0.0;
  double volume = CalculateVolumeByRisk(sym, type, entry, sl, InpRiskPerTradePct, InpMaxFreeMarginUsagePct, estMargin);
  if(volume <= 0.0)
  {
    Print("Error: Calculated volume <= 0. Aborting entry.");
    return false;
  }

  // Final free margin & margin level validations
  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(freeMargin <= 0 || estMargin > freeMargin)
  {
    PrintFormat("Error: Insufficient free margin. Need=%.2f Free=%.2f", estMargin, freeMargin);
    return false;
  }
  if(InpMinMarginLevelPct > 0)
  {
    // Predict post-trade margin roughly: current margin + estMargin
    double curMargin = AccountInfoDouble(ACCOUNT_MARGIN);
    double equity    = AccountInfoDouble(ACCOUNT_EQUITY);
    double postMargin = curMargin + estMargin;
    if(postMargin > 0)
    {
      double postML = (equity/postMargin)*100.0;
      if(postML < InpMinMarginLevelPct)
      {
        PrintFormat("Info: Predicted Margin Level %.2f%% below threshold %.2f%% after entry. Block.", postML, InpMinMarginLevelPct);
        return false;
      }
    }
  }

  // Respect freeze/stops for SL/TP distance at placement time
  double minStop = gStopsLevelPoints * gPoint;
  if(gStopsLevelPoints>0)
  {
    if(ptype==POSITION_TYPE_BUY)
    {
      if((entry - sl) < minStop) sl = NormalizePrice(entry - minStop);
      if((tp - entry) < minStop) tp = NormalizePrice(entry + minStop);
    }
    else
    {
      if((sl - entry) < minStop) sl = NormalizePrice(entry + minStop);
      if((entry - tp) < minStop) tp = NormalizePrice(entry - minStop);
    }
  }

  trade.SetMagic(InpMagicNumber);
  trade.SetDeviationInPoints(InpSlippagePoints);

  bool ok=false;
  if(type==ORDER_TYPE_BUY)
    ok = trade.Buy(volume, sym, entry, sl, tp, "EMA_RSI_ATR Buy");
  else
    ok = trade.Sell(volume, sym, entry, sl, tp, "EMA_RSI_ATR Sell");

  if(!ok)
  {
    Print("Error: Order send failed. Retcode=", trade.ResultRetcode(), " ", trade.ResultRetcodeDescription());
    return false;
  }

  PrintFormat("Order placed: %s vol=%.2f price=%.5f SL=%.5f TP=%.5f estMargin=%.2f",
              (type==ORDER_TYPE_BUY?"BUY":"SELL"), volume, entry, sl, tp, estMargin);
  return true;
}

//----------------------------------------------
// EA Events
//----------------------------------------------
int OnInit()
{
  const string sym = _Symbol;

  if(!RefreshSymbolInfo(sym))
  {
    Print("OnInit error: invalid symbol trading properties.");
    return INIT_FAILED;
  }

  if(!InitIndicators(sym, InpTimeframe))
  {
    Print("OnInit error: indicators initialization failed.");
    return INIT_FAILED;
  }

  ParseSkipHours(InpSkipHoursUTC);

  // Preload indicator data
  double dummy1,dummy2,dummy3,dummy4;
  if(!ReadIndicators(sym, InpTimeframe, 0, dummy1,dummy2,dummy3,dummy4))
    Print("Warning: Could not read initial indicator values (may resolve when data loads).");

  Print("EA initialized successfully.");
  return INIT_SUCCEEDED;
}

void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

void OnTick()
{
  const string sym = _Symbol;

  // Safety: ensure symbol info up to date
  if(!RefreshSymbolInfo(sym)) return;

  // Manage existing position trailing
  double emaF, emaS, rsi, atr;
  if(!ReadIndicators(sym, InpTimeframe, 0, emaF, emaS, rsi, atr)) return;

  if(InpAllowTrailing && atr>0)
    ManageTrailing(sym, atr);

  // Entries only on new closed bar to reduce noise
  MqlRates rates[];
  if(CopyRates(sym, InpTimeframe, 0, 3, rates) < 3) return;
  ArraySetAsSeries(rates, true);
  datetime lastClosedBarTime = rates[1].time;
  if(gLastSignalBarTime == lastClosedBarTime) return;

  // Pre-entry filters and one-position-per-symbol rule
  if(!PreEntryChecks(sym)) return;

  double atrForSignal=0.0;
  int signal = GenerateSignal(sym, InpTimeframe, atrForSignal);
  if(signal==0) return;

  // Avoid duplicate signal actions on same bar
  gLastSignalBarTime = lastClosedBarTime;

  // Place order with SL/TP and risk checks
  PlaceOrderWithSLTP(sym, signal, atrForSignal);
}

